    .replace(LIST_INDICATOR_REGEX, "")
    .replace(/[\\/:]/g, "")
    .replace(/\s+/g, " ")
    .trim();

const extractListPrefix = (line: string): string =>
  line.match(LIST_INDICATOR_REGEX)?.[0] ?? "";

