impl='''  /** One pass over the metadata cache's tag index; only files with a hit are read. */
  getCandidateNodes = async (
    nodeTypes: DiscourseNode[],
  ): Promise<DiscourseNodeCandidate[]> => {
    const nodeTypeByTag = new Map<string, DiscourseNode>();
    for (const nodeType of nodeTypes) {
      if (nodeType.tag) nodeTypeByTag.set(nodeType.tag.toLowerCase(), nodeType);
    }
    if (!nodeTypeByTag.size) return [];

    const hitsByFile: { file: TFile; hits: { line: number; nodeType: DiscourseNode }[] }[] = [];
    for (const file of this.app.vault.getMarkdownFiles()) {
      const hits: { line: number; nodeType: DiscourseNode }[] = [];
      for (const tagCache of this.app.metadataCache.getFileCache(file)?.tags ?? []) {
        const nodeType = nodeTypeByTag.get(tagCache.tag.slice(1).toLowerCase());
        if (nodeType) hits.push({ line: tagCache.position.start.line, nodeType });
      }
      if (hits.length) hitsByFile.push({ file, hits });
    }

    const perFile = await Promise.all(
      hitsByFile.map(async ({ file, hits }) => {
        const lines = (await this.app.vault.cachedRead(file)).split("\\n");
        return hits.map(({ line, nodeType }) => ({
          file,
          title: titleFromTaggedLine(lines[line] ?? ""),
          nodeTypeId: nodeType.id,
          tagLine: { line, tag: nodeType.tag! },
        }));
      }),
    );
    return perFile.flat();
  };

