import { App, Scope, setIcon } from "obsidian";
import { useEffect, useRef, type ReactElement, type ReactNode } from "react";

/** Which toolbar panel is open, so two can never be open at once. */
export type SearchDropdownId = "type-filter" | "sort" | null;

export const SearchDropdown = ({
  app,
  ariaLabel,
  badgeCount = 0,
  children,
  iconName,
  isActive,
  isDisabled = false,
  isOpen,
  onOpenChange,
  panelClassName = "w-64",
  title,
}: {
  app: App;
  ariaLabel: string;
  badgeCount?: number;
  children: ReactNode;
  iconName: string;
  isActive: boolean;
  isDisabled?: boolean;
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  panelClassName?: string;
  title: string;
}): ReactElement => {
  const containerRef = useRef<HTMLDivElement | null>(null);

  // Obsidian's modal Escape is registered before React exists, and wins on its own scope too, so only a pushed scope gets it first.
  useEffect(() => {
    if (!isOpen) return;
    const scope = new Scope();
    scope.register([], "Escape", () => {
      onOpenChange(false);
      return false;
    });
    app.keymap.pushScope(scope);
    return () => app.keymap.popScope(scope);
  }, [app, isOpen, onOpenChange]);

  // `activeDocument`, so the listener lands in the popout window holding the modal.
  useEffect(() => {
    if (!isOpen) return;
    const handlePointerDown = (event: MouseEvent) => {
      if (containerRef.current?.contains(event.target as Node)) return;
      onOpenChange(false);
    };
    activeDocument.addEventListener("mousedown", handlePointerDown, true);
    return () =>
      activeDocument.removeEventListener("mousedown", handlePointerDown, true);
  }, [isOpen, onOpenChange]);

  return (
    <div
      ref={containerRef}
      className="relative shrink-0"
      onKeyDown={(event) => {
        if (!isOpen) return;
        // Panel keystrokes must not reach the modal's Enter and arrow result navigation; Escape never arrives here at all.
        event.stopPropagation();
      }}
    >
      <button
        type="button"
        aria-expanded={isOpen}
        aria-label={ariaLabel}
        disabled={isDisabled}
        title={title}
        onClick={() => onOpenChange(!isOpen)}
        // Keeps focus in the search input, so arrow and Enter navigation stays live.
        onMouseDown={(event) => event.preventDefault()}
        className={`clickable-icon relative ${isOpen || isActive ? "is-active" : ""}`}
      >
        <span
          className="flex items-center"
          ref={(el) => (el && setIcon(el, iconName)) || undefined}
        />
        {badgeCount > 0 && (
          <span
            aria-hidden
            className="bg-accent text-on-accent pointer-events-none absolute -right-1 -top-1 flex h-3.5 min-w-3.5 items-center justify-center rounded-lg px-1 text-xs font-semibold leading-none"
          >
            {badgeCount}
          </span>
        )}
      </button>
      {isOpen && (
        <div
          className={`border-modifier-border absolute right-0 top-full z-50 mt-1 overflow-hidden rounded-md border bg-primary shadow-[shadow:var(--shadow-s)] ${panelClassName}`}
        >
          {children}
        </div>
      )}
    </div>
  );
};
import { App, setIcon } from "obsidian";
import type { KeyboardEvent, ReactElement } from "react";
import { SearchDropdown } from "~/components/SearchDropdown";
import {
  SORT_OPTIONS,
  getDefaultDirectionForKey,
  getSortDirectionLabel,
  getSortOptionLabel,
  isDefaultSort,
  type SortDirection,
  type SortKey,
} from "~/utils/discourseNodeSort";

const DIRECTIONS: { direction: SortDirection; label: string }[] = [
  { direction: "asc", label: "Asc" },
  { direction: "desc", label: "Desc" },
];

// Rows are divs, so Enter and Space have to be wired up the way a button gets them free.
const activateOnKey = (
  event: KeyboardEvent<HTMLDivElement>,
  activate: () => void,
): void => {
  if (event.key !== "Enter" && event.key !== " ") return;
  event.preventDefault();
  activate();
};

const getDirectionIconName = (direction: SortDirection): string =>
  direction === "asc" ? "arrow-up-narrow-wide" : "arrow-down-wide-narrow";

/** Rows are divs, not buttons: Obsidian's button chrome reads as separate widgets rather than a menu. */
const SortOptionRow = ({
  isSelected,
  label,
  onSelect,
}: {
  isSelected: boolean;
  label: string;
  onSelect: () => void;
}): ReactElement => (
  <div
    role="menuitemradio"
    aria-checked={isSelected}
    tabIndex={0}
    onClick={onSelect}
    onKeyDown={(event) => activateOnKey(event, onSelect)}
    onMouseDown={(event) => event.preventDefault()}
    className={`flex cursor-pointer items-center gap-2 px-3 py-1.5 text-sm ${
      isSelected
        ? "bg-accent text-on-accent"
        : "text-normal hover:bg-modifier-hover"
    }`}
  >
    {/* Always occupies its slot, so selecting an option does not shift the labels. */}
    <span className="flex w-4 shrink-0 justify-center">
      {isSelected && (
        <span ref={(el) => (el && setIcon(el, "check")) || undefined} />
      )}
    </span>
    <span className="truncate">{label}</span>
  </div>
);

const DirectionToggle = ({
  onSelect,
  sortDirection,
  sortKey,
}: {
  onSelect: (direction: SortDirection) => void;
  sortDirection: SortDirection;
  sortKey: SortKey;
}): ReactElement => (
  <div className="border-modifier-border flex gap-1 border-t p-2">
    {DIRECTIONS.map(({ direction, label }) => (
      <div
        key={direction}
        role="button"
        aria-pressed={direction === sortDirection}
        tabIndex={0}
        title={getSortDirectionLabel({ sortKey, direction })}
        onClick={() => onSelect(direction)}
        onKeyDown={(event) => activateOnKey(event, () => onSelect(direction))}
        onMouseDown={(event) => event.preventDefault()}
        className={`flex flex-1 cursor-pointer items-center justify-center gap-1 rounded px-2 py-1 text-sm ${
          direction === sortDirection
            ? "bg-accent text-on-accent"
            : "text-normal hover:bg-modifier-hover"
        }`}
      >
        <span
          className="flex items-center"
          ref={(el) =>
            (el && setIcon(el, getDirectionIconName(direction))) || undefined
          }
        />
        {label}
      </div>
    ))}
  </div>
);

export const NodeSortMenu = ({
  app,
  isOpen,
  onOpenChange,
  onSortChange,
  sortDirection,
  sortKey,
}: {
  app: App;
  isOpen: boolean;
  onOpenChange: (isOpen: boolean) => void;
  onSortChange: (next: { sortKey: SortKey; direction: SortDirection }) => void;
  sortDirection: SortDirection;
  sortKey: SortKey;
}): ReactElement => {
  const directionLabel = getSortDirectionLabel({
    sortKey,
    direction: sortDirection,
  });

  return (
    <SearchDropdown
      app={app}
      ariaLabel={`Sort by ${getSortOptionLabel(sortKey)}, ${directionLabel}`}
      iconName={getDirectionIconName(sortDirection)}
      isActive={!isDefaultSort({ sortKey, direction: sortDirection })}
      isOpen={isOpen}
      onOpenChange={onOpenChange}
      panelClassName="w-56"
      title={`Sort by ${getSortOptionLabel(sortKey)} — ${directionLabel}`}
    >
      <div role="group" className="pb-1">
        <div className="text-muted px-3 pb-1 pt-2 text-xs">Sort by</div>
        {SORT_OPTIONS.map((option) => (
          <SortOptionRow
            key={option.key}
            isSelected={option.key === sortKey}
            label={option.label}
            onSelect={() =>
              onSortChange({
                sortKey: option.key,
                direction:
                  option.key === sortKey
                    ? sortDirection
                    : getDefaultDirectionForKey(option.key),
              })
            }
          />
        ))}
      </div>
      <DirectionToggle
        onSelect={(direction) => onSortChange({ sortKey, direction })}
        sortDirection={sortDirection}
        sortKey={sortKey}
      />
    </SearchDropdown>
  );
};
